import { handleApiResponse } from "../utils/response-formatter.ts";
import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { ErrorCode } from "../utils/error-codes.ts";
import { EnhancedApi } from "../constants/api.ts";
import { assertValidIpAddress } from "../utils/validator.ts";
import type {
    IThreatDetection,
    IBlockedIp,
    IHighRiskIp,
    IReputationStats,
    ISecurityEvent,
    ISecurityEventParams,
    IIpStatus,
    ISecurityPolicy,
    ISecurityRule,
    ISecurityConfig,
} from "../models/types.ts";
import { BaseApi } from "../utils/base-api.ts";

/**
 * Security API - Security-related API endpoints
 * Provides threat detection, IP blocking, security policy management and other functions
 */
export class SecurityApi extends BaseApi {
    private readonly endpoint = EnhancedApi.SECURITY;

    /**
     * Create a SecurityApi instance
     * @param httpClient - HTTP client instance
     */
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    /**
     * Get all security policies
     * @returns Security policy list
     */
    public async getPolicies(): Promise<ISecurityPolicy[]> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                policies?: ISecurityPolicy[];
            };
            error?: string;
        }>(`${this.endpoint}/policies`, {});

        const data = handleApiResponse(response, "Failed to get security policies");
        return data.policies || [];
    }

    /**
     * Detect threats in content
     * @param content - Content to be checked
     * @param context - Optional context information
     * @returns Threat detection results
     */
    public async detectThreats(content: string, context?: Record<string, unknown>): Promise<IThreatDetection> {
        const body: Record<string, unknown> = {
            action: "detect",
            content,
        };

        if (context) {
            body.context = context;
        }

        const response = await this.httpClient.post<{
            status: string;
            data?: IThreatDetection;
            error?: string;
        }>(this.endpoint, body);

        return (
            handleApiResponse(response, "Failed to detect threats") || {
                threats: [],
                scan_id: "",
                scanned_at: "",
                status: "clean",
                safe: true,
            }
        );
    }

    /**
     * Block IP address
     * @param params - Blocking parameters
     * @param params.ip_address - IP address to block
     * @param params.reason - Blocking reason, optional
     * @param params.duration_hours - Blocking duration in hours, optional
     * @param params.permanent - Whether to block permanently, optional
     * @returns Whether the operation was successful
     */
    public async blockIp(params: {
        ip_address: string;
        reason?: string;
        duration_hours?: number;
        permanent?: boolean;
    }): Promise<boolean> {
        // Validate IP address format before sending request
        assertValidIpAddress(params.ip_address);

        const body: Record<string, unknown> = {
            ip: params.ip_address,
        };

        if (params.reason) {
            body.reason = params.reason;
        }
        if (params.duration_hours !== undefined) {
            body.duration_hours = params.duration_hours;
        }
        if (params.permanent !== undefined) {
            body.permanent = params.permanent;
        }

        const response = await this.httpClient.post<{
            status: string;
            error?: string;
        }>(`${this.endpoint}/block-ip`, body);

        handleApiResponse(response, "Failed to block IP");
        return true;
    }

    /**
     * Unblock IP address
     * @param ipAddress - IP address to unblock
     * @returns Whether the operation was successful
     */
    public async unblockIp(ipAddress: string): Promise<boolean> {
        // Validate IP address format before sending request
        assertValidIpAddress(ipAddress);

        const response = await this.httpClient.post<{
            status: string;
            error?: string;
        }>(this.endpoint, {
            action: "unblock",
            ip_address: ipAddress,
        });

        handleApiResponse(response, "Failed to unblock IP");
        return true;
    }

    /**
     * Get IP address status
     * @param ipAddress - IP address to query
     * @returns IP status information (whether blocked, reputation score, etc.)
     */
    public async getIpStatus(ipAddress: string): Promise<IIpStatus> {
        // Validate IP address format before sending request
        assertValidIpAddress(ipAddress);

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                blocked?: boolean;
                reputation_score?: number;
                last_checked?: string;
                threat_score?: number;
            };
            error?: string;
        }>(this.endpoint, {
            action: "ip_status",
            ip_address: ipAddress,
        });

        const data = handleApiResponse(response, "Failed to get IP status");

        return {
            ip: ipAddress,
            blocked: data.blocked || false,
            reputation_score: data.reputation_score || 0,
            last_checked: data.last_checked || new Date().toISOString(),
            threat_score: data.threat_score,
        };
    }

    /**
     * Get blocked IP list
     * @returns Blocked IP list
     */
    public async getBlockedIps(): Promise<IBlockedIp[]> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                blocked_ips?: IBlockedIp[];
            };
            error?: string;
        }>(this.endpoint, {
            action: "blocked_ips",
        });

        const data = handleApiResponse(response, "Failed to get blocked IPs");
        return data.blocked_ips || [];
    }

    /**
     * Get high risk IP list
     * @param threshold - Risk score threshold, optional, defaults to all high risk IPs
     * @returns High risk IP list
     */
    public async getHighRiskIps(threshold?: number): Promise<IHighRiskIp[]> {
        const params: Record<string, unknown> = {
            action: "high_risk_ips",
        };

        if (threshold !== undefined) {
            params.threshold = threshold;
        }

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                high_risk_ips?: IHighRiskIp[];
            };
            error?: string;
        }>(this.endpoint, params);

        const data = handleApiResponse(response, "Failed to get high risk IPs");
        return data.high_risk_ips || [];
    }

    /**
     * Get reputation statistics
     * @returns Reputation statistics information
     */
    public async getReputationStats(): Promise<IReputationStats> {
        const response = await this.httpClient.get<{
            status: string;
            data?: IReputationStats;
            error?: string;
        }>(this.endpoint, {
            action: "reputation_stats",
        });

        return (
            handleApiResponse(response, "Failed to get reputation stats") || {
                total_blocked: 0,
                active_blocked: 0,
                high_risk_count: 0,
                average_threat_score: 0,
            }
        );
    }

    /**
     * Get security event list
     * @param params - Optional query parameters (user ID, event type, severity, limit, etc.)
     * @returns Security event list
     */
    public async getSecurityEvents(params?: ISecurityEventParams): Promise<ISecurityEvent[]> {
        const queryParams: Record<string, unknown> = {
            action: "events",
        };

        if (params?.user_id) {
            queryParams.user_id = params.user_id;
        }
        if (params?.event_type) {
            queryParams.event_type = params.event_type;
        }
        if (params?.severity) {
            queryParams.severity = params.severity;
        }
        if (params?.limit !== undefined) {
            queryParams.limit = params.limit;
        }
        if (params?.offset !== undefined) {
            queryParams.offset = params.offset;
        }

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                events?: ISecurityEvent[];
            };
            error?: string;
        }>(this.endpoint, queryParams);

        const data = handleApiResponse(response, "Failed to get security events");
        return data.events || [];
    }

    /**
     * Resolve (close) security event
     * @param eventId - Event ID
     * @returns Whether the operation was successful
     */
    public async resolveEvent(eventId: string): Promise<boolean> {
        const response = await this.httpClient.post<{
            status: string;
            error?: string;
        }>(this.endpoint, {
            action: "resolve_event",
            event_id: eventId,
        });

        handleApiResponse(response, "Failed to resolve event");
        return true;
    }

    // =========================================================================
    // Security Policies CRUD Operations
    // =========================================================================

    /**
     * Create new security policy
     * @param params - Policy parameters
     * @param params.name - Policy name
     * @param params.description - Policy description, optional
     * @param params.rules - Policy rule list
     * @param params.enabled - Whether to enable, optional
     * @returns Created policy
     */
    public async createPolicy(params: {
        name: string;
        description?: string;
        rules: ISecurityRule[];
        enabled?: boolean;
    }): Promise<ISecurityPolicy> {
        if (!params.name || typeof params.name !== "string" || params.name.trim().length === 0) {
            throw this.createError("Policy name is required and must be a non-empty string", ErrorCode.INVALID_PARAM);
        }

        if (!params.rules || !Array.isArray(params.rules) || params.rules.length === 0) {
            throw this.createError("Policy rules are required and must be a non-empty array", ErrorCode.INVALID_PARAM);
        }

        const response = await this.httpClient.post<{
            status: string;
            data?: ISecurityPolicy;
            error?: string;
        }>(`${this.endpoint}/policies/create`, params);

        return handleApiResponse(response, "Failed to create security policy");
    }

    /**
     * Update security policy
     * @param policyId - Policy ID
     * @param updates - Update content
     * @returns Updated policy
     */
    public async updatePolicy(
        policyId: string,
        updates: Partial<Omit<ISecurityPolicy, "id" | "created_at">>,
    ): Promise<ISecurityPolicy> {
        if (!policyId || typeof policyId !== "string" || policyId.trim().length === 0) {
            throw this.createError("Policy ID is required and must be a non-empty string", ErrorCode.INVALID_PARAM);
        }

        const response = await this.httpClient.put<{
            status: string;
            data?: ISecurityPolicy;
            error?: string;
        }>(`${this.endpoint}/policies/${policyId}`, updates);

        return handleApiResponse(response, "Failed to update security policy");
    }

    /**
     * Delete security policy
     * @param policyId - Policy ID
     * @returns Whether the operation was successful
     */
    public async deletePolicy(policyId: string): Promise<boolean> {
        if (!policyId || typeof policyId !== "string" || policyId.trim().length === 0) {
            throw this.createError("Policy ID is required and must be a non-empty string", ErrorCode.INVALID_PARAM);
        }

        const response = await this.httpClient.request<{
            status: string;
            error?: string;
        }>(`${this.endpoint}/policies/${policyId}`, {
            method: "DELETE",
        });

        handleApiResponse(response, "Failed to delete security policy");
        return true;
    }

    /**
     * Set policy enabled status
     * @param policyId - Policy ID
     * @param enabled - Whether to enable
     * @returns Updated policy
     */
    public async setPolicyEnabled(policyId: string, enabled: boolean): Promise<ISecurityPolicy> {
        return this.updatePolicy(policyId, { enabled });
    }

    /**
     * Add rule to policy
     * @param policyId - Policy ID
     * @param rule - Rule to add
     * @returns Updated policy
     */
    public async addPolicyRule(policyId: string, rule: ISecurityRule): Promise<ISecurityPolicy> {
        if (!policyId || typeof policyId !== "string" || policyId.trim().length === 0) {
            throw this.createError("Policy ID is required and must be a non-empty string", ErrorCode.INVALID_PARAM);
        }

        if (!rule || typeof rule !== "object") {
            throw this.createError("Rule must be a valid object", ErrorCode.INVALID_PARAM);
        }

        const response = await this.httpClient.post<{
            status: string;
            data?: ISecurityPolicy;
            error?: string;
        }>(`${this.endpoint}/policies/${policyId}/rules`, { action: "add", rule });

        return handleApiResponse(response, "Failed to add policy rule");
    }

    /**
     * Remove rule from policy
     * @param policyId - Policy ID
     * @param ruleIndex - Rule index
     * @returns Updated policy
     */
    public async removePolicyRule(policyId: string, ruleIndex: number): Promise<ISecurityPolicy> {
        if (!policyId || typeof policyId !== "string" || policyId.trim().length === 0) {
            throw this.createError("Policy ID is required and must be a non-empty string", ErrorCode.INVALID_PARAM);
        }

        if (typeof ruleIndex !== "number" || ruleIndex < 0) {
            throw this.createError("Rule index must be a non-negative number", ErrorCode.INVALID_PARAM);
        }

        const response = await this.httpClient.post<{
            status: string;
            data?: ISecurityPolicy;
            error?: string;
        }>(`${this.endpoint}/policies/${policyId}/rules`, { action: "remove", rule_index: ruleIndex });

        return handleApiResponse(response, "Failed to remove policy rule");
    }

    /**
     * Get security configuration
     * @returns Security configuration information
     */
    public async getConfig(): Promise<ISecurityConfig> {
        const response = await this.httpClient.get<{
            status: string;
            data?: ISecurityConfig;
            error?: string;
        }>(`${this.endpoint}/config`);

        return handleApiResponse(response, "Failed to get security config");
    }

    /**
     * Update security configuration
     * @param config - Configuration updates
     * @returns Updated security configuration
     */
    public async updateConfig(config: Partial<ISecurityConfig["settings"]>): Promise<ISecurityConfig> {
        const response = await this.httpClient.put<{
            status: string;
            data?: ISecurityConfig;
            error?: string;
        }>(`${this.endpoint}/config`, config);

        return handleApiResponse(response, "Failed to update security config");
    }
}
